        old_publish = (
            f"        for (int d = 0; d < {D}; ++d) Jr[d] = Zi[d * ZS];   // Jr holds this lane's row of Z from here on"
        )
        assert ink_stage.count(old_publish) == 1
        publication = f"        for (int d = 0; d < {D}; ++d) s_Yt[d * YS + i] = Jr[d];"
